```python

def with_error_handling(node_name: str):

def decorator(fn):

@wraps(fn)

def wrapper(state, *args, **kwargs):

try:

return fn(state, *args, **kwargs)

except Exception as e:

logger.exception("Node '%s' failed: %s", node_name, e)

